parameters.inputSchema:
{
  "type": "object",
  "properties": {
    "action": { "type": "string", "enum": ["add", "update", "delete", "other"] },
    "date_text": { "type": ["string", "null"], "description": "the day/date words exactly as the user wrote them" },
    "time": { "type": ["string", "null"], "description": "24-hour HH:mm" },
    "purpose": { "type": ["string", "null"] }
  },
  "required": ["action", "date_text", "time", "purpose"]
}

parameters.jsCode:
const out = $input.first().json.output;
const msg = String($('When chat message received').first().json.chatInput || '').toLowerCase();
const today = $now.startOf('day');

const months = ['jan','feb','mar','apr','may','jun','jul','aug','sep','oct','nov','dec'];
const weekdays = ['monday','tuesday','wednesday','thursday','friday','saturday','sunday'];

// DATE: only trust date words that really appear in the user's message
const alias = { tmr: 'tomorrow', tmrw: 'tomorrow', tmw: 'tomorrow' };
const skip = ['the','on','of','this','next','st','nd','rd','th'];
const grounded = w => w === 'tomorrow' ? /tomorrow|tmr|tmw/.test(msg) : (msg.includes(w) || msg.includes(w.slice(0, 3)));
const dateWords = (out.date_text || '').toLowerCase().split(/\W+/)
  .filter(w => w && !skip.includes(w))
  .map(w => alias[w] || w);
const text = dateWords.length > 0 && dateWords.every(grounded) ? dateWords.join(' ') : '';
const tokens = text.split(' ');

let date = null;

if (text) {
  if (text.includes('day after tomorrow')) {
    date = today.plus({ days: 2 });
  } else if (tokens.includes('tomorrow')) {
    date = today.plus({ days: 1 });
  } else if (tokens.includes('today')) {
    date = today;
  } else {
    const wd = weekdays.findIndex(d => tokens.some(w => w.length >= 3 && d.startsWith(w)));
    if (wd !== -1) {
      let diff = (wd + 1) - today.weekday;
      if (diff <= 0) diff += 7;
      date = today.plus({ days: diff });
    } else {
      const m = months.findIndex(mo => tokens.some(w => w.startsWith(mo)));
      const dayMatch = text.match(/\d{1,2}/);
      if (m !== -1 && dayMatch) {
        const dnum = Number(dayMatch[0]);
        let d = today.set({ month: m + 1, day: dnum });
        if (d.isValid && d.day === dnum) {
          if (d < today) d = d.plus({ years: 1 });
          date = d;
        }
      }
    }
  }
}

// TIME: read times from the user's message; the model's value must match one of them
const found = [];
for (const m of msg.matchAll(/(\d{1,2})(?::(\d{2}))?\s*(am|pm)\b/g)) {
  let h = Number(m[1]) % 12;
  if (m[3] === 'pm') h += 12;
  found.push(String(h).padStart(2, '0') + ':' + (m[2] || '00'));
}
for (const m of msg.matchAll(/\b([01]?\d|2[0-3]):([0-5]\d)\b(?!\s*(?:am|pm))/g)) found.push(m[1].padStart(2, '0') + ':' + m[2]);
if (/\bnoon\b/.test(msg)) found.push('12:00');
if (/\bmidnight\b/.test(msg)) found.push('00:00');
const time = out.time && found.includes(out.time) ? out.time : null;

// PURPOSE: only the reason itself, and every word must appear in the message
const stop = ['book','booking','schedule','reserve','slot','visit','set','up','make','need','want','get','cancel','cancelling','delete','remove','update','change','move','reschedule','push','shift','me','a','an','the','my','i','to','for','at','on','please','pls','appointment','tomorrow','today','tmr','tmrw','tmw','next','this','noon','am','pm','st','nd','rd','th','of','it','instead','yo','hey'];
const dayNames = [...months, ...weekdays, 'mon','tue','tues','wed','thu','thur','thurs','fri','sat','sun'];
const pWords = (out.purpose || '').toLowerCase().split(/\W+/)
  .filter(w => w && !/^\d+$/.test(w) && !stop.includes(w) && !dayNames.includes(w));
const purpose = pWords.length > 0 && pWords.every(w => msg.includes(w)) ? pWords.join(' ') : null;

// ACTION: a booking verb with nothing usable is not a request
let action = out.action;
const intent = /book|appoint|schedul|reserv|cancel|delet|remov|move|chang|push|shift|slot/.test(msg);
if (['add','update','delete'].includes(action) && !intent && !text && !time && !purpose) action = 'other';

const isAdd = action === 'add';
const isUpdateOrDelete = action === 'update' || action === 'delete';

return [{
  json: {
    action,
    date: date ? date.toFormat('yyyy-MM-dd') : null,
    time,
    purpose,
    readyToAdd: !!(isAdd && date && time && purpose),
    needsLookup: !!(isUpdateOrDelete && purpose),
  },
}];

const items = $input.all();
const ctx = $('Code in JavaScript').first().json;

if (items.length === 0) {
  return [{ json: { ...ctx, matchStatus: 'none' } }];
}

let matches = items;

const stop = ['book','booking','cancel','cancelling','delete','remove','update','change','move','reschedule','me','a','an','the','my','appointment','please'];
const cleanedPurpose = (ctx.purpose || '').toLowerCase().split(/\W+/).filter(w => w && !stop.includes(w)).join(' ');

if (cleanedPurpose) {
  matches = items.filter(i => (i.json.summary || '').toLowerCase().includes(cleanedPurpose));
}

if (matches.length > 1 && ctx.time && ctx.action !== 'update') {
  const byTime = matches.filter(i => (i.json.start?.dateTime || '').includes('T' + ctx.time));
  if (byTime.length > 0) matches = byTime;
}

if (matches.length === 1) {
  const start = matches[0].json.start.dateTime || matches[0].json.start.date;
  return [{
    json: {
      ...ctx,
      matchStatus: 'found',
      eventId: matches[0].json.id,
      eventSummary: matches[0].json.summary,
      eventStart: start,
      newDate: ctx.date || start.split('T')[0],
      newTime: ctx.time || (start.split('T')[1] || '00:00').slice(0, 5),
      hasChange: !!(ctx.date || ctx.time),
    },
  }];
}

return [{
  json: {
    ...ctx,
    matchStatus: matches.length === 0 ? 'none' : 'multiple',
    candidates: matches.map(i => `${i.json.summary} at ${i.json.start.dateTime || i.json.start.date}`),
  },
}];
